// Auth pages use the same original site mark as the header, including the
// bundled xiaoqilogo fallback when a configured image cannot be loaded.
const authBrandStyle = `<style>.cms-body .auth h2{display:flex;align-items:center;justify-content:center;gap:10px;line-height:1.4}.cms-body .auth h2 .sx-auth-brand-logo{display:inline-block;width:32px;height:32px;min-width:32px;max-width:32px;object-fit:contain;flex-shrink:0;border-radius:8px;background:#fff}</style>`
const authBrandLogo = `<img class="sx-auth-brand-logo" src="{{if .SiteLogo}}{{.SiteLogo}}{{else}}` + defaultLogoURL + `{{end}}" alt="{{.SiteName}} LOGO" width="32" height="32" onerror="this.onerror=null;this.src='` + defaultLogoURL + `'">`

const authSubmitScript = `<script>(function(){
 const form=document.querySelector('.auth-wrap form.auth');if(!form)return;
 form.addEventListener('submit',async function(event){
  event.preventDefault();const button=form.querySelector('button[type="submit"],button.btn-main');
  const original=button?.textContent||'';if(button)button.disabled=true;
  let result=form.querySelector('.sx-auth-result');if(!result){result=document.createElement('p');result.className='sx-auth-result';result.setAttribute('role','status');result.style.cssText='color:#ef5b58;margin-top:12px;text-align:center';form.appendChild(result)}
  result.textContent='';
  try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin'});
   if(response.redirected){location.assign(response.url);return}
   const message=(await response.text()).trim();
   if(!response.ok)throw Error(message.slice(0,180)||'提交失败，请稍后重试');
   const data=JSON.parse(message);if(data.code!==0&&data.code!==1)throw Error(data.message||data.msg||'提交失败');
   location.assign(data.data?.redirect||'/suxinvideo/center');
  }catch(error){result.textContent=error.message||'网络异常';const captcha=form.querySelector('.sx-captcha-img');if(captcha)captcha.click();if(window.turnstile)window.turnstile.reset()}
  finally{if(button){button.disabled=false;button.textContent=original}}
 });
})();</script>`

const loginThemeBody = authBrandStyle + `<div class="auth-wrap"><form class="auth" method="post" action="/suxinvideo/login"><h2>` + authBrandLogo + `登录{{.SiteName}}</h2><div class="fi"><label>邮箱</label><input class="sx-input" name="email" type="email" required autocomplete="email" placeholder="example@qq.com"></div><div class="fi"><label>密码</label><input class="sx-input" name="password" type="password" required autocomplete="current-password"></div>{{.CaptchaWidget}}<button class="btn-main">登录</button>{{if .RegistrationEnabled}}<a class="btn-line" href="/suxinvideo/register">没有账号？立即注册</a>{{end}}{{if .PasswordResetEnabled}}<a class="btn-line" href="/suxinvideo/forgot">忘记密码？</a>{{end}}<p class="alt">连续登录失败 5 次将暂时锁定账号</p></form></div>` + authSubmitScript

const registerThemeBody = authBrandStyle + `<div class="auth-wrap"><form class="auth" id="register-form" method="post" action="/suxinvideo/register"><h2>` + authBrandLogo + `注册{{.SiteName}}</h2><div class="fi"><label>邮箱</label><input class="sx-input" name="email" type="email" required></div><div class="fi"><label>昵称</label><input class="sx-input" name="name" required></div><div class="fi"><label>密码</label><input class="sx-input" name="password" type="password" minlength="6" required></div>{{if .RegistrationRequiresEmailCode}}<div class="fi"><label>邮箱验证码</label><input class="sx-input" name="email_code" required><button id="send-code" class="btn-line" type="button">发送验证码</button></div>{{end}}{{.CaptchaWidget}}<button type="submit" class="btn-main">立即注册</button><a class="btn-line" href="/suxinvideo/login">已有账号？去登录</a>{{if .RegistrationRequiresEmailCode}}<p id="send-result" role="status"></p>{{end}}</form></div>{{if .RegistrationRequiresEmailCode}}<script>(function(){const form=document.getElementById('register-form'),button=document.getElementById('send-code'),output=document.getElementById('send-result');if(!form||!button||!output)return;button.onclick=async()=>{button.disabled=true;const data=new FormData();data.set('email',form.elements.email.value);['captcha','cf-turnstile-response','lot_number','captcha_output','pass_token','gen_time'].forEach(k=>{if(form.elements[k])data.set(k,form.elements[k].value)});try{const response=await fetch('/suxinvideo/sendcode',{method:'POST',body:data,credentials:'same-origin'}),text=await response.text();let result;try{result=JSON.parse(text)}catch(e){throw Error(text.slice(0,160))}if(!response.ok)throw Error(result.message||result.msg||'发送失败');output.textContent='验证码已发送'}catch(e){output.textContent=e.message}finally{button.disabled=false;const img=document.getElementById('sx-captcha-img');if(img)img.src='/suxinvideo/captcha?t='+Date.now();if(window.turnstile)window.turnstile.reset();if(window.sxGeetest)window.sxGeetest.reset()}}})();</script>{{end}}` + authSubmitScript

const forgotThemeBody = `{{if .PasswordResetEnabled}}<div class="auth-wrap"><form class="auth" id="reset-form" method="post" action="/suxinvideo/forgot"><h2>找回密码</h2><div class="fi"><label>注册邮箱</label><input class="sx-input" name="email" type="email" required></div>{{.CaptchaWidget}}<div class="fi"><button id="reset-code" class="btn-line" type="button">发送重置码</button></div><div class="fi"><label>邮箱重置码</label><input class="sx-input" name="code" required></div><div class="fi"><label>新密码</label><input class="sx-input" name="password" type="password" minlength="6" required></div><div class="fi"><label>确认密码</label><input class="sx-input" name="repassword" type="password" minlength="6" required></div><button class="btn-main">重置密码</button><a class="btn-line" href="/suxinvideo/login">返回登录</a><p id="reset-result" role="status"></p></form></div><script>(function(){const form=document.getElementById('reset-form'),button=document.getElementById('reset-code'),output=document.getElementById('reset-result');if(!form||!button||!output)return;button.onclick=async()=>{button.disabled=true;const data=new FormData();data.set('email',form.elements.email.value);data.set('purpose','reset');['captcha','cf-turnstile-response','lot_number','captcha_output','pass_token','gen_time'].forEach(k=>{if(form.elements[k])data.set(k,form.elements[k].value)});try{const response=await fetch('/suxinvideo/sendcode',{method:'POST',body:data,credentials:'same-origin'}),text=await response.text();let result;try{result=JSON.parse(text)}catch(e){throw Error(text.slice(0,160))}if(!response.ok)throw Error(result.message||result.msg||'发送失败');output.textContent='重置码已发送'}catch(e){output.textContent=e.message}finally{button.disabled=false;const img=document.getElementById('sx-captcha-img');if(img)img.src='/suxinvideo/captcha?t='+Date.now();if(window.turnstile)window.turnstile.reset();if(window.sxGeetest)window.sxGeetest.reset()}}})();</script>{{else}}<div class="auth-wrap"><section class="auth" aria-labelledby="reset-unavailable"><h2 id="reset-unavailable">找回密码</h2><p role="status">本站暂未开启邮箱找回密码功能，请联系管理员重置密码。</p><a class="btn-line" href="/suxinvideo/login">返回登录</a></section></div>{{end}}` + authSubmitScript

