const accountPageScript = `<script>(function(){
 document.querySelectorAll('[data-account-time]').forEach(node=>{const value=node.dataset.accountTime;if(/^\d{10,13}$/.test(value)){const date=new Date(Number(value)*(value.length===10?1000:1));if(!Number.isNaN(date.getTime()))node.textContent=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)}});
 document.querySelectorAll('form[data-account-submit]').forEach(form=>form.addEventListener('submit',async event=>{
  event.preventDefault();const button=form.querySelector('button[type="submit"]'),output=form.querySelector('.sx-account-result');button.disabled=true;output.textContent='正在提交…';
  try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin'});if(response.redirected){location.assign(response.url);return}const raw=(await response.text()).trim();if(!response.ok)throw Error(raw.slice(0,180)||'提交失败，请稍后重试');let result;try{result=JSON.parse(raw)}catch(error){throw Error('服务器返回异常，请稍后重试')}if(result.code!==0&&result.code!==1)throw Error(result.message||result.msg||'提交失败');location.assign(result.data?.redirect||'/suxinvideo/center')}
  catch(error){output.textContent=error.message||'网络异常，请稍后重试'}finally{button.disabled=false}
 }));
})();</script>`

func accountPageData(user row, extra map[string]any) map[string]any {
	remaining := gconv.Int64(user["vip_expire"]) - time.Now().Unix()
	data := map[string]any{"User": user, "IsVIP": remaining > 0, "VIPDays": (remaining + 86399) / 86400}
	for key, value := range extra {
		data[key] = value
	}
	return data
}

func accountPageBody(active, content string) string {
	nav := strings.Replace(accountNavigation, `href="/suxinvideo/`+active+`"`, `class="on" aria-current="page" href="/suxinvideo/`+active+`"`, 1)
	return accountPageStyle + `<section class="sx-account-page" aria-label="个人中心">{{if eq .Theme "suxinlite"}}<header class="uc-head"><div class="uc-av">` + accountProfileImage + `</div><div class="sx-account-identity"><div class="uc-nm">{{.User.name}}</div><div class="uc-em" title="{{.User.email}}">{{.User.email}}</div></div><div class="uc-badges"><div class="uc-badge"><b>{{if .IsVIP}}VIP · {{.VIPDays}} 天{{else}}未开通{{end}}</b><span>会员状态</span></div><div class="uc-badge"><b>{{.User.points}}</b><span>积分余额</span></div></div></header><nav class="uc-tabs sx-account-nav" aria-label="个人中心菜单">` + nav + `</nav>{{else}}<div class="uc sx-account-layout"><aside class="uc-side"><div class="me"><div class="av">` + accountProfileImage + `</div><div><b>{{.User.name}}</b><span title="{{.User.email}}">{{.User.email}}</span></div></div><div class="vip"><div>会员状态</div><b>{{if .IsVIP}}VIP · {{.VIPDays}} 天{{else}}未开通{{end}}</b></div><div class="vip"><div>积分余额</div><b>{{.User.points}}</b></div><nav class="uc-menu sx-account-nav" aria-label="个人中心菜单">` + nav + `</nav></aside>{{end}}<div class="uc-main sx-account-content">` + content + `</div>{{if ne .Theme "suxinlite"}}</div>{{end}}</section>` + accountPageScript
}

var centerThemeBody = accountPageBody("center", `<h2>我的账户</h2><div class="sx-account-actions"><form method="post" action="/suxinvideo/sign" data-account-submit><button type="submit" class="btn-main">每日签到 +{{.SignPoints}} 积分</button><p class="sx-account-result" role="status"></p></form><a class="btn-main sx-account-vip-action" href="/suxinvideo/pay">开通或续费 VIP</a></div><p class="sx-account-help">签到可获得积分，用于解锁单片；VIP 有效期内可观看会员影片。</p><section class="sx-account-section"><h3>修改昵称</h3><form class="sx-account-form" method="post" action="/suxinvideo/account" data-account-submit><input type="hidden" name="act" value="nickname"><label class="sx-account-field"><span>昵称</span><input class="sx-input" name="name" minlength="2" maxlength="20" value="{{.User.name}}" required autocomplete="nickname" placeholder="2–20 个字符"></label><button type="submit" class="btn-main">保存昵称</button><p class="sx-account-result" role="status"></p></form></section><section class="sx-account-section"><h3>修改密码</h3><form class="sx-account-form" method="post" action="/suxinvideo/account" data-account-submit><input type="hidden" name="act" value="password"><label class="sx-account-field"><span>当前密码</span><input class="sx-input" name="oldpwd" type="password" required autocomplete="current-password"></label><label class="sx-account-field"><span>新密码</span><input class="sx-input" name="newpwd" type="password" minlength="6" maxlength="72" required autocomplete="new-password" placeholder="至少 6 个字符"></label><label class="sx-account-field"><span>确认新密码</span><input class="sx-input" name="repwd" type="password" minlength="6" maxlength="72" required autocomplete="new-password" placeholder="再次输入新密码"></label><button type="submit" class="btn-main">修改密码</button><p class="sx-account-result" role="status"></p></form></section>`)

var historyThemeBody = accountPageBody("history", `<div class="sx-page-heading"><h2>观看历史</h2>{{if .Records}}<form method="post" action="/suxinvideo/history/clear"><button type="submit" class="btn-line" onclick="return confirm('确定清空全部观看历史？')">清空历史</button></form>{{end}}</div><div class="hist-grid">{{range .Records}}<div class="hist-card"><a class="hp" href="/suxinvideo/play?id={{.id}}&episode={{.episode_index}}"><img src="{{pic .pic}}" loading="lazy" alt="{{.name}}"><span class="rm">看到第 {{.episode}} 集</span><div class="prog"><i style="width:100%"></i></div></a><a class="hnm" href="/suxinvideo/detail?id={{.id}}">{{.name}}</a><div class="hmeta">看到第 {{.episode}} 集</div></div>{{else}}<p class="sx-empty">暂无观看记录，去看几部影片吧</p>{{end}}</div>`)

var favoritesThemeBody = accountPageBody("favorites", `<div class="sx-page-heading"><h2>我的收藏</h2></div>{{template "cards" .Vods}}`)

var ordersThemeBody = accountPageBody("orders", `<h2>充值订单</h2><div class="sx-account-orders"><table class="ut"><thead><tr><th scope="col">订单号</th><th scope="col">套餐</th><th scope="col">金额</th><th scope="col">方式</th><th scope="col">状态</th><th scope="col">时间</th></tr></thead><tbody>{{range .Orders}}<tr><td data-label="订单号"><a href="/suxinvideo/pay/result?ono={{.order_no}}">{{.order_no}}</a></td><td data-label="套餐">{{.title}}</td><td data-label="金额">¥{{.amount}}</td><td data-label="方式">{{.pay_type}}</td><td data-label="状态">{{if eq (str .status) "1"}}<span class="sx-order-paid">已支付</span>{{else if eq (str .status) "2"}}已取消{{else}}<span class="sx-order-pending">待支付</span>{{end}}</td><td data-label="时间"><time data-account-time="{{.created}}">{{.created}}</time></td></tr>{{else}}<tr><td colspan="6">暂无订单</td></tr>{{end}}</tbody></table></div>`)
